const fetch = require('node-fetch');

// Configuration
const API_KEY = 'ck_test_1234567890abcdef'; // Bug 1: Using client-side key (ck_) instead of server-side (sk_)
const API_BASE_URL = 'https://crossmint.com/api/'; // Bug 4: Wrong base URL (should be staging)

// NFT metadata
const nftMetadata = {
  name: 'My Awesome NFT',
  description: 'This is a test NFT minted via Crossmint',
  // Bug 3: Missing required 'image' field
};

// Recipient address
const recipient = 'email|user@example.com|polygon-amoy'; // Bug 2: Wrong format (pipe separators instead of colons)

async function mintNFT() {
  try {
    const response = await fetch(`${API_BASE_URL}2022-06-09/chains/polygon-amoy/collections`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-API-KEY': API_KEY,
      },
      body: JSON.stringify({
        metadata: nftMetadata,
        recipients: [recipient],
      }),
    });

    const data = await response.json();

    // Write response to file
    const fs = require('fs');
    fs.writeFileSync('/home/user/fixed_mint_response.json', JSON.stringify(data, null, 2));

    console.log('NFT mint response:', data);
    process.exit(0);
  } catch (error) {
    console.error('Error minting NFT:', error);
    process.exit(1);
  }
}

mintNFT();

